"use client"

import * as React from "react"
import { TrendingDown, TrendingUp } from "lucide-react"

import { cn } from "@/lib/utils"
import { type NumberFormat } from "@/registry/dashboardcn/lib/format"
import { Card, CardContent } from "@/components/ui/card"
import { RadialGauge } from "@/registry/dashboardcn/ui/radial-gauge"
import { MetricValue } from "@/registry/dashboardcn/ui/metric-value"

export interface RingKpiMetric {
  label: string
  value: number
  /** Previous value, shown as "up from" or "down from". */
  previous?: number
  /** Ring fill from 0 to 100. Defaults to value as a share of max. */
  progress?: number
  /** Upper bound used to fill the ring when progress is not given. */
  max?: number
  format?: NumberFormat
  currency?: string
  /** Suffix after the number, e.g. "ms" or "req/s". */
  unit?: string
  /** Treat a decrease as good (latency, errors). */
  invertDelta?: boolean
  /** Slot in the top-right corner, e.g. a menu button. */
  action?: React.ReactNode
}

export interface RingKpiCardProps extends React.ComponentProps<typeof Card> {
  metrics: RingKpiMetric[]
}

function RingKpiValue({
  metric,
  value,
  className,
}: {
  metric: RingKpiMetric
  value: number
  className?: string
}) {
  return (
    <MetricValue
      value={value}
      format={metric.format}
      currency={metric.currency}
      maximumFractionDigits={metric.format ? undefined : 1}
      suffix={metric.unit ? ` ${metric.unit}` : undefined}
      className={className}
    />
  )
}

/** A card with a row of KPI tiles, each with a segmented ring next to the value and a comparison to the previous value. */
function RingKpiCard({ metrics, className, ...props }: RingKpiCardProps) {
  return (
    <Card
      data-slot="ring-kpi-card"
      className={cn("overflow-hidden py-0", className)}
      {...props}
    >
      <CardContent className="px-0">
        {/* Tiles wrap to fit and stretch to fill their row; the gap shows the border color as hairline dividers. */}
        <div className="bg-border flex flex-wrap gap-px">
          {metrics.map((metric) => {
            const direction =
              metric.previous === undefined || metric.previous === metric.value
                ? "flat"
                : metric.value > metric.previous
                  ? "up"
                  : "down"
            const positive =
              direction === "flat" ? null : (direction === "up") !== Boolean(metric.invertDelta)
            const color =
              positive === false ? "var(--color-red-500)" : "var(--color-emerald-500)"
            const progress =
              metric.progress ??
              (metric.max ? (metric.value / metric.max) * 100 : 0)
            const Icon = direction === "down" ? TrendingDown : TrendingUp
            return (
              <div
                key={metric.label}
                data-slot="ring-kpi-metric"
                className="bg-card flex min-w-0 flex-[1_1_13rem] flex-col gap-4 p-5"
              >
                <div className="flex items-center justify-between gap-2">
                  <span className="text-muted-foreground truncate text-sm">{metric.label}</span>
                  {metric.action ? <span className="shrink-0">{metric.action}</span> : null}
                </div>
                <div className="flex items-center gap-3">
                  <RadialGauge
                    value={progress}
                    sweep={360}
                    size={40}
                    thickness={4}
                    segments={14}
                    gap={7}
                    color={color}
                  />
                  <RingKpiValue
                    metric={metric}
                    value={metric.value}
                    className="truncate text-2xl font-semibold tracking-tight"
                  />
                </div>
                {metric.previous !== undefined ? (
                  <span
                    data-direction={direction}
                    data-positive={positive}
                    className={cn(
                      "text-muted-foreground flex flex-wrap items-center gap-x-1.5 gap-y-0.5 text-xs",
                      positive === true && "[&_[data-accent]]:text-emerald-600 dark:[&_[data-accent]]:text-emerald-400",
                      positive === false && "[&_[data-accent]]:text-red-600 dark:[&_[data-accent]]:text-red-400"
                    )}
                  >
                    {direction !== "flat" ? (
                      <Icon data-accent="" className="size-3.5" aria-hidden="true" />
                    ) : null}
                    {direction === "flat" ? "unchanged from" : direction === "up" ? "up from" : "down from"}{" "}
                    <RingKpiValue
                      metric={metric}
                      value={metric.previous}
                      data-accent=""
                      className="font-medium"
                    />
                  </span>
                ) : null}
              </div>
            )
          })}
        </div>
      </CardContent>
    </Card>
  )
}

export { RingKpiCard }

import * as React from "react"

import { cn } from "@/lib/utils"

export interface RadialGaugeProps extends React.ComponentProps<"div"> {
  value: number
  min?: number
  max?: number
  /** Diameter in pixels. */
  size?: number
  /** Stroke width in pixels. */
  thickness?: number
  /** Number of arc segments. 0 draws a continuous arc. */
  segments?: number
  /** Gap between segments in degrees. */
  gap?: number
  /** Angle where the arc starts, in degrees clockwise from 12 o'clock. */
  startAngle?: number
  /** Total sweep of the arc in degrees. 180 is a semicircle, 360 a ring. */
  sweep?: number
  /** Any CSS color. Defaults to chart-1. */
  color?: string
  trackColor?: string
  /** Content rendered in the middle of the gauge. */
  children?: React.ReactNode
}

// Round so server and client render identical path strings.
const round = (n: number) => Math.round(n * 1000) / 1000

function polar(cx: number, cy: number, r: number, angleDeg: number) {
  const rad = ((angleDeg - 90) * Math.PI) / 180
  return { x: round(cx + r * Math.cos(rad)), y: round(cy + r * Math.sin(rad)) }
}

function arcPath(cx: number, cy: number, r: number, from: number, to: number) {
  const start = polar(cx, cy, r, from)
  const end = polar(cx, cy, r, to)
  const largeArc = to - from > 180 ? 1 : 0
  return `M ${start.x} ${start.y} A ${r} ${r} 0 ${largeArc} 1 ${end.x} ${end.y}`
}

function RadialGauge({
  value,
  min = 0,
  max = 100,
  size = 160,
  thickness = 10,
  segments = 0,
  gap = 2,
  startAngle,
  sweep = 180,
  color = "var(--chart-1)",
  trackColor = "var(--muted)",
  className,
  children,
  ...props
}: RadialGaugeProps) {
  const fraction = Math.min(1, Math.max(0, (value - min) / (max - min || 1)))
  const start = startAngle ?? (sweep >= 360 ? 0 : -sweep / 2)
  const r = size / 2 - thickness / 2
  const cx = size / 2
  const cy = size / 2
  // Trim the box to the arc's vertical extent so a semicircle does not
  // reserve a full circle of space.
  const angles = Array.from({ length: 64 }, (_, i) => start + (sweep * i) / 63)
  const ys = angles.map((a) => polar(cx, cy, r, a).y)
  const top = Math.max(0, Math.min(...ys) - thickness / 2)
  const bottom = Math.min(size, Math.max(...ys) + thickness / 2)
  const height = bottom - top

  const arcs: { from: number; to: number; filled: boolean }[] = []
  if (segments > 0) {
    const step = sweep / segments
    for (let i = 0; i < segments; i++) {
      const from = start + i * step + gap / 2
      const to = start + (i + 1) * step - gap / 2
      const mid = (i + 0.5) / segments
      arcs.push({ from, to, filled: mid <= fraction })
    }
  }

  return (
    <div
      data-slot="radial-gauge"
      role="meter"
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn("relative inline-flex shrink-0", className)}
      style={{ width: size, height }}
      {...props}
    >
      <svg
        width={size}
        height={height}
        viewBox={`0 ${top} ${size} ${height}`}
        className="absolute inset-0"
        aria-hidden="true"
      >
        {segments > 0 ? (
          arcs.map((arc, index) => (
            <path
              key={index}
              d={arcPath(cx, cy, r, arc.from, arc.to)}
              fill="none"
              stroke={arc.filled ? color : trackColor}
              strokeWidth={thickness}
              strokeLinecap="butt"
            />
          ))
        ) : (
          <>
            <path
              d={arcPath(cx, cy, r, start, start + sweep - (sweep >= 360 ? 0.01 : 0))}
              fill="none"
              stroke={trackColor}
              strokeWidth={thickness}
              strokeLinecap={sweep >= 360 ? "butt" : "round"}
            />
            {fraction > 0 ? (
              <path
                d={arcPath(cx, cy, r, start, start + sweep * fraction)}
                fill="none"
                stroke={color}
                strokeWidth={thickness}
                strokeLinecap="round"
                className="transition-[d] duration-500"
              />
            ) : null}
          </>
        )}
      </svg>
      {children ? (
        <div
          className={cn(
            "absolute inset-x-0 flex flex-col items-center justify-center text-center",
            sweep > 200 ? "inset-y-0" : "bottom-0"
          )}
        >
          {children}
        </div>
      ) : null}
    </div>
  )
}

export { RadialGauge }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

/** Values at or above this are abbreviated by default. */
export const DEFAULT_COMPACT_FROM = 100_000

export interface MetricValueProps extends Omit<React.ComponentProps<"span">, "children"> {
  /** Strings render as-is. */
  value: number | string
  format?: NumberFormat
  currency?: string
  maximumFractionDigits?: number
  /** Values at or above this are abbreviated (e.g. $158K) with the full value in a tooltip. Set to Infinity to always show the full value. */
  compactFrom?: number
  /** Text after the number, e.g. a unit. */
  suffix?: React.ReactNode
}

/** A formatted number. Large values are abbreviated and reveal the full value on hover. */
function MetricValue({
  value,
  format,
  currency,
  maximumFractionDigits,
  compactFrom = DEFAULT_COMPACT_FROM,
  suffix,
  className,
  ...props
}: MetricValueProps) {
  const classes = cn("tabular-nums", className)

  if (typeof value !== "number") {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {value}
        {suffix}
      </span>
    )
  }

  const full = formatNumber(value, { format, currency, maximumFractionDigits })
  const abbreviate = format !== "percent" && Math.abs(value) >= compactFrom
  if (!abbreviate) {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {full}
        {suffix}
      </span>
    )
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <span
            data-slot="metric-value"
            data-compact=""
            className={cn(classes, "cursor-default")}
            {...props}
          >
            {formatNumber(value, { format, currency, compact: true })}
            {suffix}
          </span>
        </TooltipTrigger>
        <TooltipContent className="tabular-nums">
          {full}
          {suffix}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

export { MetricValue }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
  /** Abbreviate large values, e.g. "$158K" instead of "$158,143". */
  compact?: boolean
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(158143, { format: "currency", compact: true }) -> "$158K"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
    compact = false,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  // Compact values keep three significant digits: $158K, $1.23M, 41.2K.
  const compactOptions: Intl.NumberFormatOptions = compact
    ? maximumFractionDigits === undefined
      ? { notation: "compact", maximumSignificantDigits: 3 }
      : { notation: "compact", maximumFractionDigits }
    : {}
  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
        ...compactOptions,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
        ...compactOptions,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
